pub fn is_prime(n: i8) -> bool {
    // Handle all values < 2 (including negatives) as non-prime.
    if n < 2 {
        return false;
    }

    // Loop over candidate divisors in increasing order.
    let mut k: i8 = 2;

    // Invariants intended throughout the loop:
    // - n >= 2
    // - 2 <= k <= n
    // - For all j with 2 <= j < k: n % j != 0
    //
    // Termination measure (well-founded, strictly decreases each iteration):
    //   (n as i16) - (k as i16)
    while k < n {
        // If a divisor is found, n is not prime by the definition.
        if n % k == 0 {
            return false;
        }

        // Decrease the measure by incrementing k by 1.
        // Old measure: (n - k), new measure: (n - (k+1)) = old - 1.
        k += 1;
    }

    // If the loop completes, no k with 2 <= k < n divides n.
    // Therefore, n is prime under the given definition.
    true
}